function followPage(owners:string[]){if(!current)return;const seat=current.package.seats.find(s=>s.ownerIds.some(id=>owners.includes(id))&&!s.continuation);if(!seat)return;const pages=viewportFit(innerWidth,innerHeight,effectiveView(current.personal.view),current.package.pages.length).pages;if(!pages.includes(seat.page)){current.personal.view.page=seat.page;renderPages();renderToolbar();}}
function stopPerformance(){performanceGeneration++;const run=performanceRun,clock=performanceClock;performanceClock=undefined;if(run){run.session.pause();cancelAnimationFrame(run.raf);}clock?.close();performanceRun=undefined;app.querySelector('.performance-hud')?.remove();app.querySelector('.performance-count')?.remove();}
async function performanceDialog(){if(!current)return;requirePianoCapability(current.package,'pianoPerformance');stopPerformance();const target=current,reference=requireReferencePerformanceTempo(target.package.score),records=readPerformance((await readJson(performanceStorageName(target.entry.id,target.package)))??(legacyPerformanceStorageName(target.package)?await readJson(legacyPerformanceStorageName(target.package)!):undefined),target.package.manifest.revision,reference),prior=(await readJson<{working?:number;audioOutput?:string}>(practiceStorageName(target.entry.id,target.package)))??(legacyPracticeStorageName(target.package)?await readJson<{working?:number;audioOutput?:string}>(legacyPracticeStorageName(target.package)!):undefined),bpm=prior?.working??reference.bpm;const d=showDialog(`<h2>Performance</h2><label class="dialog-row practice-reference">Tempo <span class="metronome-mark">${manualTempoField('performance',`<input data-performance-duration data-absolute="${bpm}" data-presented="${speedNumber(bpm,reference.bpm)}" type="text" inputmode="decimal" value="${speedNumber(bpm,reference.bpm)}" aria-label="Performance tempo, percent of score reference">`,'performance tempo','<span aria-hidden="true">%</span>')}</span></label><p class="dialog-row practice-reference">Score reference ${metronomeMark(reference)}</p><p class="help">Play the full score at the chosen tempo. Notes and timing are checked; fingerings remain available.</p>${Object.values(records.best).sort((a,b)=>a.bpm-b.bpm).map(r=>`<p class="help">${metronomeMark(reference,r.bpm)} · ${accuracyLabel(r.accuracy)} · ${r.correct}/${r.expected} notes · ${r.extra} extra</p>`).join('')}<div class="dialog-actions"><button data-performance-start>Start</button><button data-action="close">Cancel</button></div><p class="error" role="alert"></p>`,'performance');let selectedBpm=bpm;const durationField=d.querySelector<HTMLInputElement>('[data-performance-duration]')!,durationError=d.querySelector('.error')!;const readDuration=(field:HTMLInputElement)=>{const next=field.value===field.dataset.manualDraftText?Number(field.dataset.manualDraft):speedEdit(field.value,selectedBpm,reference.bpm,durationField.dataset.presented);if(!Number.isFinite(next)||next<5||next>500)throw Error('Choose a tempo from 5 to 500 per minute.');return next;};const commitDuration=()=>{try{selectedBpm=readDuration(durationField);durationField.value=speedNumber(selectedBpm,reference.bpm);durationField.dataset.absolute=String(selectedBpm);durationField.dataset.presented=durationField.value;durationError.textContent='';return true;}catch(error){performanceControls?.cancel();durationError.textContent=(error as Error).message;return false;}};durationField.addEventListener('change',commitDuration);performanceControls=new ManualTempoControls({accepts:el=>d.isConnected&&d.contains(el),edit:{cancel:()=>{durationError.textContent='';},commit:()=>commitDuration(),adjust:(_key,field,direction,elapsed)=>{try{const current=readDuration(field),next=adjustPercent(current,reference.bpm,direction);if(next===current)return false;field.value=speedNumber(next,reference.bpm);field.dataset.manualDraft=String(next);field.dataset.manualDraftText=field.value;durationError.textContent='';return true;}catch(error){durationError.textContent=(error as Error).message;return false;}}},adjust:(_key,direction,repeated,elapsed)=>{if(!repeated&&!commitDuration())return false;const next=adjustPercent(selectedBpm,reference.bpm,direction);if(next===selectedBpm)return false;selectedBpm=next;const from=durationField.selectionStart,to=durationField.selectionEnd;durationField.value=speedNumber(next,reference.bpm);durationField.dataset.absolute=String(next);durationField.dataset.presented=durationField.value;if(document.activeElement===durationField&&from!==null&&to!==null)durationField.setSelectionRange(Math.min(from,durationField.value.length),Math.min(to,durationField.value.length));return true;}});d.querySelector('[data-performance-start]')!.addEventListener('click',async()=>{let startingGeneration:number|undefined;try{if(!commitDuration())return;const playingBpm=selectedBpm;if(!midiConnection)throw Error('Connect your piano in Options first.');stopPerformance();const generation=performanceGeneration;startingGeneration=generation;const ports=await practiceAudio.outputs();if(generation!==performanceGeneration||!d.isConnected||current!==target)return;const clock=new PracticeClock(ports.supported,preferences.audioOutput??'',performanceAudioErrorHandler(generation,()=>performanceGeneration,stopPerformance,notify)),plan=planPerformance(target.package);performanceClock=clock;closeDialog();selection=undefined;editSequence.reset();readerPreview?.clear();readerContacts.clear();target.personal.view.page=0;toolbarVisible=false;renderPages();renderToolbar();const start=await clock.begin(playingBpm,practiceTiming(playingBpm).countInMs+plan.totalTicks*scoreTickMs(plan,playingBpm)+1000,true,plan.grid);if(generation!==performanceGeneration)return;const session=new PerformanceSession(plan,playingBpm,start,musicalSustain.snapshot());performanceRun={session,clock,records,entryId:target.entry.id,raf:0,generation};const hud=document.createElement('div');hud.className='performance-hud';hud.innerHTML=`<small data-performance-status>Performance · ${metronomeMark(reference,playingBpm)}</small><button data-action="performance-stop">Stop <kbd>Esc</kbd></button>`;app.append(hud);const cue=document.createElement('div');cue.className='performance-count';app.append(cue);const frame=()=>{const run=performanceRun;if(!run||run.generation!==generation)return;session.update(clock.now());cue.hidden=session.phase!=='countin';if(!cue.hidden)cue.textContent=String(Math.min(1,Math.max(0,Math.floor((clock.now()-(session.startMs-practiceTiming(playingBpm).countInMs))/practiceTiming(playingBpm).goalBeatMs)))+1);if(session.phase==='complete'){void clock.stop();const result=session.result()!;recordPerformance(records,result);hud.querySelector('[data-performance-status]')!.innerHTML=`${accuracyLabel(result.accuracy)} · ${metronomeMark(reference,playingBpm)} · ${result.correct}/${result.expected} notes · ${result.extra} extra`;void writeJson(performanceStorageName(target.entry.id,target.package),records).catch(error=>notify(`Performance was not saved: ${error.message}`));return;}run.raf=requestAnimationFrame(frame);};frame();}catch(error){if(startingGeneration!==undefined&&(startingGeneration!==performanceGeneration||!d.isConnected&&!performanceClock))return;stopPerformance();if(d.isConnected)d.querySelector('.error')!.textContent=(error as Error).message;else notify((error as Error).message);}});}

function paintLibrarySummaries(){if(current||practice)return;if(dialog){librarySummaryPaintPending=true;return;}renderLibrary();}
const libraryProgressContext=()=>JSON.stringify([preferences.keyboardLayout,entries.map(entry=>[entry.id,entry.file])]);
async function loadPracticeTotals(){const context=libraryProgressContext(),keyboard=preferences.keyboardLayout;
 return practiceSummaries.refresh(entries,keyboard,{readPackage:file=>host.read(file),readRecord:file=>readJson(file)},()=>context===libraryProgressContext());
}
async function refreshLibrarySummaries(){if(await loadPracticeTotals())paintLibrarySummaries();}

async function boot(){calibration=await loadCalibration(host);try{const lib=await readJson<{version:number;entries:Entry[]}>('library.json');if(lib){if(lib.version!==1||!Array.isArray(lib.entries)||lib.entries.some(e=>!validEntryStorage(e)))throw Error('Library identity differs; data retained');entries=lib.entries;}const saved=await readJson<typeof preferences>('preferences.json');if(saved){if(saved.version!==1||![0,90,180,270].includes(saved.libraryRotation))throw Error('Preferences version differs; data retained');preferences={...saved,keyboardLayout:keyboardPreference(saved.keyboardLayout,entries.some(e=>e.id==='e363c2897ab1a85fb6a4178ab1514987d7b6d207be92b56a90dbb0a5a5d5bc27')),bindings:readBindings(saved.bindings),...fingerPreferences(saved),midi:readMidiMapping(saved.midi),midiBindings:saved.midiBindings===undefined?undefined:readMidiBindings(saved.midiBindings,saved.midi)};}if(preferences.lastWorkedEntryId!==undefined&&(typeof preferences.lastWorkedEntryId!=='string'||!/^[a-f0-9]{64}$/.test(preferences.lastWorkedEntryId)))throw Error('Saved score selection differs; data retained');if(preferences.audioOutput!==undefined&&typeof preferences.audioOutput!=='string')throw Error('Saved audio output differs; data retained');try{pianoSettings=readPianoPreferences(preferences.piano);}catch(error){pianoSettings=defaultPianoPreferences();pianoWarning=(error as Error).message;}orientation=new ViewerOrientation(preferences);input=new InputController(preferences.bindings);mainControls=readControlBindings(preferences.controlBindings,preferences);preferences.freeViewControls=readFreeViewControlOverrides(preferences.freeViewControls,mainControls);controls.configure(mainControls);await host.onFocusChange(focused=>{if(!focused)loseFocus();else readerFocused=true;});await host.onMidi(onMidi,status=>{if(status.generation===midiConnection?.generation){bindingOptions?.connectionChanged();musicalSustain.clear();midiConnection=undefined;bindingOptions?.paint();stopPerformance();readerPreview?.clear();readerContacts.clear();paintReaderContacts();practice?.pause();resetInput();practice?.pause();notify(status.message);midiOptions?.lost(status.message);}},onMidiNote);await loadPracticeTotals();render();await host.fullscreen(true);void enqueue(()=>configurePiano()).catch(error=>{pianoWarning=`Piano sound is off: ${error.message}`;});}catch(error){app.innerHTML='<p class="error">The library could not open. Your saved files have been retained.</p>';notify((error as Error).message);}}
void boot();
